// ── Snapshot Selection ───────────────────────────────────────────────

export function selectSnapshotForModel(
	report: CodexUsageReport,
	model: CodexUsageModel | undefined,
): NormalizedRateLimitSnapshot | undefined {
	const codexSnapshot = report.snapshots.find(isPrimaryCodexSnapshot);
	if (!model || !isOpenAICodexModel(model)) return codexSnapshot ?? report.snapshots[0];

	const modelKeys = normalizedModelUsageKeys(model);
	const exactMatch = report.snapshots.find((snapshot) =>
		normalizedSnapshotUsageKeys(snapshot).some((key) => modelKeys.has(key)),
	);
	if (exactMatch) return exactMatch;

	const variants = codexModelVariantKeys(modelKeys);
	for (const variant of variants) {
		const matches = report.snapshots.filter(
			(snapshot) =>
				!isPrimaryCodexSnapshot(snapshot) &&
				normalizedSnapshotUsageKeys(snapshot).some((key) =>
					normalizedKeyHasToken(key, variant),
				),
		);
		if (matches.length === 1) return matches[0];
	}

	return codexSnapshot ?? report.snapshots[0];
}

// ── Internal Formatting Helpers ──────────────────────────────────────

function isPrimaryCodexSnapshot(snapshot: NormalizedRateLimitSnapshot): boolean {
	return (
		normalizedUsageKey(snapshot.limitId) === "codex" ||
		normalizedUsageKey(snapshot.limitName) === "codex"
	);
}

function formatWindowLine(label: string, window: NormalizedRateLimitWindow): string {
	return `  ${label.padEnd(LIMIT_VALUE_COLUMN)}${formatWindow(window)}`;
}

function formatWindow(window: NormalizedRateLimitWindow): string {
	const remaining = 100 - clampPercent(window.usedPercent);
	const reset = window.resetsAt ? ` (resets ${formatReset(window.resetsAt)})` : "";
	return `${progressBar(remaining)} ${remaining.toFixed(0)}% left${reset}`;
}

function progressBar(percentRemaining: number): string {
	const filled = Math.round((clampPercent(percentRemaining) / 100) * BAR_SEGMENTS);
	return `[${"█".repeat(filled)}${"░".repeat(BAR_SEGMENTS - filled)}]`;
}

export function formatCredits(credits: NormalizedCredits): string {
	if (!credits.hasCredits) return "no credits";
	if (credits.unlimited) return "unlimited credits";
	const balance = credits.balance?.trim();
	if (!balance) return "credits available";
	return `${formatNumber(Number(balance), balance)} credits`;
}

function formatReset(epochSeconds: number): string {
	const reset = new Date(epochSeconds * 1000);
	if (Number.isNaN(reset.getTime())) return "at an unknown time";

	const now = new Date();
	const time = `${reset.getHours().toString().padStart(2, "0")}:${reset
		.getMinutes()
		.toString()
		.padStart(2, "0")}`;
	if (reset.toDateString() === now.toDateString()) return time;
	const day = reset.getDate().toString();
	const month = reset.toLocaleDateString(undefined, { month: "short" });
	return `${time} on ${day} ${month}`;
}

function formatNumber(value: number, fallback: string): string {
	if (!Number.isFinite(value)) return fallback;
	return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(value);
}

function clampPercent(value: number): number {
	if (!Number.isFinite(value)) return 0;
	return Math.min(100, Math.max(0, value));
}

// ── Snapshot Key Matching ────────────────────────────────────────────

function normalizedModelUsageKeys(model: CodexUsageModel): Set<string> {
	const keys = new Set<string>();
	addNormalizedUsageKey(keys, model.id);
	addNormalizedUsageKey(keys, model.name);

	for (const key of [...keys]) {
		const codexIndex = key.indexOf("codex");
		if (codexIndex >= 0) keys.add(key.slice(codexIndex));
	}

	return keys;
}

function normalizedSnapshotUsageKeys(snapshot: NormalizedRateLimitSnapshot): string[] {
	return [normalizedUsageKey(snapshot.limitId), normalizedUsageKey(snapshot.limitName)].filter(
		(key): key is string => key !== undefined,
	);
}

function addNormalizedUsageKey(keys: Set<string>, value: string | undefined): void {
	const key = normalizedUsageKey(value);
	if (key) keys.add(key);
}

function normalizedUsageKey(value: string | undefined): string | undefined {
	const key = value
		?.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "");
	return key || undefined;
}

function codexModelVariantKeys(modelKeys: Set<string>): string[] {
	const variants = new Set<string>();
	for (const key of modelKeys) {
		const match = key.match(/(?:^|-)codex-(.+)$/);
		if (match?.[1]) variants.add(match[1]);
	}
	return [...variants];
}

function normalizedKeyHasToken(key: string, token: string): boolean {
	return (
		key === token ||
		key.startsWith(`${token}-`) ||
		key.endsWith(`-${token}`) ||
		key.includes(`-${token}-`)
	);
}

import type { ExtensionContext, ReadonlyFooterDataProvider } from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

import type { Chip, GitStatusPart, RuntimeState } from "./types.js";
import { ansi } from "./ansi.js";
import { chip, renderChip, renderChips, renderSegmentedChip } from "./chips.js";
import {
  formatCodexChipData,
  contextSnapshot,
  formatCost,
  formatCount,
  formatThinking,
  formatWorkingPath,
  getTokenTotals,
  modelName,
  shorten,
  smartPathTruncate,
} from "./format.js";
import { getGitSnapshot } from "./git.js";
import { COLOR, thinkingColor } from "./theme.js";

// ── Line Renderers ───────────────────────────────────────────────────

export function renderPrimaryLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
  runtime: RuntimeState,
): string {
  const context = contextSnapshot(ctx);
  const right: Chip[] = [
    chip("MODEL", modelName(ctx), COLOR.model, 1, { valueBg: COLOR.panelLift, boldValue: true }),
    chip("THINK", formatThinking(runtime.thinkingLevel), thinkingColor(runtime.thinkingLevel), 2, {
      valueBg: COLOR.panelLift,
    }),
    chip("CTX", context.label, context.color, 1, {
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  ];

  return fitLeftRight(width, right, (available) => renderPathCluster(available, ctx, footerData));
}

export function renderUsageLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
  runtime: RuntimeState,
): string {
  const totals = getTokenTotals(ctx);
  const right: Chip[] = [
    chip("↑", formatCount(totals.input), COLOR.token, 1),
    chip("↓", formatCount(totals.output), COLOR.token, 1),
    chip("$", formatCost(totals.cost), COLOR.cost, 2, { boldValue: true }),
  ];

  return fitLeftRight(width, right, (available) => renderCodexStatus(available, runtime, ctx));
}

export function renderSeparatorLine(width: number): string {
  return ansi("─".repeat(Math.max(0, width)), { fg: COLOR.separator });
}

// ── Layout ───────────────────────────────────────────────────────────

function fitLeftRight(width: number, rightChips: Chip[], renderLeft: (available: number) => string): string {
  for (let priority = 3; priority >= 1; priority -= 1) {
    const right = renderChips(rightChips.filter((item) => item.priority <= priority));
    const rightWidth = visibleWidth(right);
    const gap = rightWidth > 0 ? 1 : 0;
    const availableLeft = Math.max(0, width - rightWidth - gap);
    const left = renderLeft(availableLeft);
    const leftWidth = visibleWidth(left);

    if (leftWidth + rightWidth + gap <= width) {
      const padding = " ".repeat(Math.max(gap, width - leftWidth - rightWidth));
      return truncateToWidth(`${left}${padding}${right}`, width, "");
    }
  }

  return truncateToWidth(renderLeft(width), width, "");
}

// ── Path Cluster ─────────────────────────────────────────────────────

function renderPathCluster(maxWidth: number, ctx: ExtensionContext, footerData: ReadonlyFooterDataProvider): string {
  if (maxWidth <= 0) return "";

  const footerBranch = footerData.getGitBranch() ?? undefined;
  const git = getGitSnapshot(ctx.cwd, footerBranch);
  const branch = git.branch ?? footerBranch;
  const fullPath = formatWorkingPath(ctx.cwd);

  for (const attempt of [
    { worktreeWidth: 24, branchWidth: 28, includeStatus: true },
    { worktreeWidth: 18, branchWidth: 18, includeStatus: true },
    { worktreeWidth: 12, branchWidth: 12, includeStatus: true },
    { worktreeWidth: 18, branchWidth: 18, includeStatus: false },
    { worktreeWidth: 18, branchWidth: 0, includeStatus: false },
    { worktreeWidth: 0, branchWidth: 18, includeStatus: true },
    { worktreeWidth: 0, branchWidth: 18, includeStatus: false },
    { worktreeWidth: 0, branchWidth: 0, includeStatus: false },
  ]) {
    const worktreeChip =
      attempt.worktreeWidth > 0 && git.worktreeName ? renderWorktreeChip(git.worktreeName, attempt.worktreeWidth) : "";
    const branchChip =
      attempt.branchWidth > 0 && branch ? renderBranchChip(branch, attempt.branchWidth, attempt.includeStatus ? git.statusParts : undefined) : "";
    const fixed = [worktreeChip, branchChip].filter(Boolean).join(" ");
    const fixedWidth = visibleWidth(fixed);
    const gap = fixedWidth > 0 ? 1 : 0;
    const pathMaxWidth = Math.max(0, maxWidth - fixedWidth - gap);
    const pathChip = renderFittedPathChip(fullPath, pathMaxWidth);
    const cluster = [pathChip, fixed].filter(Boolean).join(" ");

    if (visibleWidth(cluster) <= maxWidth) return cluster;
  }

  return truncateToWidth(renderFittedPathChip(fullPath, maxWidth), maxWidth, "");
}

// ── Path Chips ───────────────────────────────────────────────────────

function renderPathChip(value: string): string {
  return renderChip(
    chip("", value, COLOR.path, 1, {
      labelFg: COLOR.black,
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  );
}

function renderFittedPathChip(path: string, maxWidth: number): string {
  if (maxWidth <= 0) return "";

  const fullPathChip = renderPathChip(path);
  if (visibleWidth(fullPathChip) <= maxWidth) return fullPathChip;

  const emptyPathChipWidth = visibleWidth(renderPathChip(""));
  const pathWidth = Math.max(3, maxWidth - emptyPathChipWidth);
  return truncateToWidth(renderPathChip(smartPathTruncate(path, pathWidth)), maxWidth, "");
}

// ── Git Chips ────────────────────────────────────────────────────────

function renderBranchChip(branch: string, maxWidth: number, statusParts?: GitStatusPart[]): string {
  const branchText = shorten(branch, maxWidth);
  const segments = [
    { text: branchText, fg: COLOR.git, bold: true },
    ...(statusParts ?? []).map((part) => ({ text: `${part.symbol}${part.count}`, fg: part.color, bold: true })),
  ];

  return renderSegmentedChip("", segments, COLOR.git, { labelFg: COLOR.black, valueBg: COLOR.panelLift });
}

function renderWorktreeChip(worktreeName: string, maxWidth: number): string {
  return renderChip(chip("󰙅", shorten(worktreeName, maxWidth), COLOR.git, 2, { labelFg: COLOR.black }));
}

// ── Codex Chip ─────────────────────────────────────────────────────

function renderCodexStatus(maxWidth: number, runtime: RuntimeState, ctx: ExtensionContext): string {
  if (maxWidth <= 0) return "";

  const manager = runtime.codexUsage;
  const data = formatCodexChipData(manager.getReport(), manager.state, ctx.model);
  const accent = data.accent;
  const labelFg = accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink;

  const full = renderSegmentedChip("CODEX", data.segments, accent, {
    labelFg,
    valueBg: COLOR.panelLift,
  });
  if (visibleWidth(full) <= maxWidth) return full;

  const emptyWidth = visibleWidth(
    renderChip(
      chip("CODEX", "", accent, 1, { labelFg, valueBg: COLOR.panelLift }),
    ),
  );
  const valueWidth = Math.max(1, maxWidth - emptyWidth);
  return truncateToWidth(
    renderChip(
      chip("CODEX", truncateToWidth(data.text, valueWidth, "…"), accent, 1, {
        labelFg,
        valueBg: COLOR.panelLift,
        boldValue: manager.state === "loaded",
      }),
    ),
    maxWidth,
    "",
  );
}

import type { ThinkingLevel } from "./types.js";

// ── Color Palette ────────────────────────────────────────────────────

export const COLOR = {
  // Text
  ink: "#f8fafc",
  soft: "#cbd5e1",
  dim: "#94a3b8",
  black: "#020617",

  // Panels
  panel: "#111827",
  panelLift: "#1f2937",
  panelSoft: "#334155",
  separator: "#1e293b",

  // Path
  path: "#38bdf8",

  // Model
  model: "#60a5fa",

  // Context usage
  contextTransparent: "#1f2937",
  contextGreen: "#22c55e",
  contextLightGreen: "#86efac",
  contextLightYellow: "#fde68a",
  contextYellow: "#eab308",
  contextOrange: "#f97316",
  contextLightRed: "#f87171",
  contextRed: "#ef4444",
  contextWarn: "#f97316",
  contextFull: "#ef4444",

  // Thinking level
  thinkOff: "#64748b",
  thinkMinimal: "#22d3ee",
  thinkLow: "#bbf7d0",
  thinkMedium: "#22c55e",
  thinkHigh: "#f97316",
  thinkXhigh: "#ef4444",

  // Codex
  codex: "#06b6d4",

  // Git
  git: "#22c55e",
  gitDirty: "#f59e0b",
  gitModified: "#38bdf8",
  gitUntracked: "#ef4444",
  gitStaged: "#22c55e",
  gitDeleted: "#ef4444",
  gitRenamed: "#a78bfa",

  // Usage
  token: "#64748b",
  cost: "#15803d",
} as const;

// ── Color Resolvers ──────────────────────────────────────────────────

export function contextColor(percent: number): string {
  if (percent < 10) return COLOR.contextGreen;
  if (percent < 25) return COLOR.contextLightGreen;
  if (percent < 40) return COLOR.contextLightYellow;
  if (percent < 55) return COLOR.contextYellow;
  if (percent < 70) return COLOR.contextOrange;
  if (percent < 85) return COLOR.contextLightRed;
  return COLOR.contextRed;
}

export function thinkingColor(level: ThinkingLevel): string {
  switch (level) {
    case "off":
      return COLOR.thinkOff;
    case "minimal":
      return COLOR.thinkMinimal;
    case "low":
      return COLOR.thinkLow;
    case "medium":
      return COLOR.thinkMedium;
    case "high":
      return COLOR.thinkHigh;
    case "xhigh":
      return COLOR.thinkXhigh;
  }
}

export function codexAccent(state: import("./codex-usage/index.js").CodexUsageState): string {
  switch (state) {
    case "idle":
      return COLOR.panelSoft;
    case "loading":
      return COLOR.contextWarn;
    case "error":
      return COLOR.contextFull;
    case "loaded":
      return COLOR.codex;
  }
}

export function codexPercentColor(percent: number): string {
  const clamped = Math.max(0, Math.min(100, percent));
  if (clamped <= 10) return COLOR.contextRed;
  if (clamped <= 25) return COLOR.contextLightRed;
  if (clamped <= 40) return COLOR.contextOrange;
  if (clamped <= 55) return COLOR.contextYellow;
  if (clamped <= 70) return COLOR.contextLightYellow;
  if (clamped <= 85) return COLOR.contextLightGreen;
  return COLOR.contextGreen;
}

