    96	async function resolvePiCodexAuth(
    97		ctx: ExtensionContext,
    98	): Promise<{ headers: Record<string, string> } | undefined> {
    99		const models = codexAuthCandidateModels(ctx);
   100		const errors: string[] = [];
   101	
   102		for (const model of models) {
   103			const auth = await ctx.modelRegistry.getApiKeyAndHeaders(model);
   104			if (!auth.ok) {
   105				errors.push(auth.error);
   106				continue;
   107			}
   108	
   109			const headers = { ...(auth.headers ?? {}) };
   110			if (!hasHeader(headers, "Authorization") && auth.apiKey) {
   111				headers.Authorization = `Bearer ${auth.apiKey}`;
   112			}
   113			if (!hasHeader(headers, "User-Agent")) {
   114				headers["User-Agent"] = "pi-codex-usage";
   115			}
   116			if (hasHeader(headers, "Authorization")) {
   117				return { headers };
   118			}
   119		}
   120	
   121		if (errors.length > 0) {
   122			throw new Error(errors.join("; "));
   123		}
   124		return undefined;
   125	}
