   127	function codexAuthCandidateModels(ctx: ExtensionContext): PiModel[] {
   128		const candidates: PiModel[] = [];
   129		const seen = new Set<string>();
   130		const add = (model: PiModel | undefined) => {
   131			if (!model || model.provider !== CODEX_PROVIDER_ID) return;
   132			const key = `${model.provider}/${model.id}`;
   133			if (seen.has(key)) return;
   134			seen.add(key);
   135			candidates.push(model);
   136		};
   137	
   138		add(ctx.model);
   139		for (const model of ctx.modelRegistry.getAvailable()) add(model);
   140		for (const model of ctx.modelRegistry.getAll()) add(model);
   141		return candidates;
