   102		}
   103	
   104		if (state === "error" || !report) {
   105			const label = state === "error" ? "usage error" : "usage —";
   106			return {
   107				text: label,
   108				segments: [{ text: label, fg: COLOR.soft }],
   109				accent: codexAccent(state),
   110			};
   111		}
   112	
   113		const snapshot = selectSnapshotForModel(report, model);
   114		if (!snapshot) {
   115			return {
   116				text: "usage unavailable",
   117				segments: [{ text: "usage unavailable", fg: COLOR.soft }],
   118				accent: codexAccent("loaded"),
   119			};
   120		}
   121	
   122		const parts: Array<{ text: string; fg: string; bold?: boolean }> = [];
   123		const textParts: string[] = [];
   124	
   125		const prefix = formatStatuslinePrefix(snapshot);
   126		if (prefix !== "codex") {
   127			parts.push({ text: prefix, fg: COLOR.soft });
   128			textParts.push(prefix);
   129		}
   130	
   131		if (snapshot.primary) {
   132			const pct = formatRemainingPercent(snapshot.primary);
   133			parts.push(
   134				{ text: pct, fg: codexPercentColor(100 - clampPercent(snapshot.primary.usedPercent)), bold: true },
   135				{ text: "5h", fg: COLOR.dim },
   136			);
   137			textParts.push(`${pct} 5h`);
   138		}
   139		if (snapshot.secondary) {
   140			const pct = formatRemainingPercent(snapshot.secondary);
   141			parts.push(
   142				{ text: pct, fg: codexPercentColor(100 - clampPercent(snapshot.secondary.usedPercent)), bold: true },
