   308	export function formatCredits(credits: NormalizedCredits): string {
   309		if (!credits.hasCredits) return "no credits";
   310		if (credits.unlimited) return "unlimited credits";
   311		const balance = credits.balance?.trim();
   312		if (!balance) return "credits available";
   313		return `${formatNumber(Number(balance), balance)} credits`;
   314	}
