   316	function formatReset(epochSeconds: number): string {
   317		const reset = new Date(epochSeconds * 1000);
   318		if (Number.isNaN(reset.getTime())) return "at an unknown time";
   319	
   320		const now = new Date();
   321		const time = `${reset.getHours().toString().padStart(2, "0")}:${reset
   322			.getMinutes()
   323			.toString()
   324			.padStart(2, "0")}`;
   325		if (reset.toDateString() === now.toDateString()) return time;
   326		const day = reset.getDate().toString();
   327		const month = reset.toLocaleDateString(undefined, { month: "short" });
   328		return `${time} on ${day} ${month}`;
   329	}
