// ── Extension Entry Point ────────────────────────────────────────────

export default function piStatus(pi: ExtensionAPI): void {
  let enabled = process.env.PI_STATUS !== "0";
  const codexUsage = new CodexUsageManager();
  const runtime: RuntimeState = {
    thinkingLevel: "off",
    codexUsage,
  };

  const refresh = () => runtime.requestRender?.();
  const refreshCodexUsage = (
    ctx: ExtensionContext,
    force = false,
    model = ctx.model,
  ) => {
    if (!enabled) return;
    void codexUsage.refresh(ctx, force, model, {
      showErrors: isOpenAICodexModel(model),
    });
  };

  const installFooter = (ctx: ExtensionContext) => {
    if (ctx.mode !== "tui") return;

    ctx.ui.setStatus(FOOTER_KEY, undefined);

    if (!enabled) {
      ctx.ui.setFooter(undefined);
      runtime.requestRender = undefined;
      codexUsage.setRenderCallback(undefined);
      codexUsage.clear();
      return;
    }

    ctx.ui.setFooter((tui, _theme, footerData) => {
      runtime.requestRender = () => tui.requestRender();
      codexUsage.setRenderCallback(() => tui.requestRender());
      const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());
      const clock = setInterval(() => tui.requestRender(), 60_000);

      return {
        dispose() {
          unsubscribeBranch();
          clearInterval(clock);
          codexUsage.setRenderCallback(undefined);
        },
        invalidate() {},
        render(width: number): string[] {
          if (width <= 0) return [""];
          return [
            renderSeparatorLine(width),
            renderPrimaryLine(width, ctx, footerData, runtime),
            renderSeparatorLine(width),
            renderUsageLine(width, ctx, footerData, runtime),
          ];
        },
      };
    });
  };

  // ── Commands ─────────────────────────────────────────────────────

  pi.registerCommand("pi-status", {
    description: "Toggle the high-contrast Pi status footer. Usage: /pi-status [on|off|toggle]",
    handler: async (args, ctx) => {
      const action = args.trim().toLowerCase();
      if (action === "on") enabled = true;
      else if (action === "off") enabled = false;
      else enabled = !enabled;

      installFooter(ctx);
      if (enabled) refreshCodexUsage(ctx);
      else codexUsage.clear();
      ctx.ui.notify(`High-contrast status footer ${enabled ? "enabled" : "disabled"}`, "info");
    },
  });

  pi.registerCommand(CODEX_COMMAND_NAME, {
    description: "Show Codex ChatGPT subscription usage and rate-limit windows",
    handler: async (args, ctx) => {
      const options = parseCodexStatusArgs(args);
      if (!options.ok) {
        ctx.ui.notify(options.error, "warning");
        return;
      }

      if (options.value.clearStatusline) {
        codexUsage.clear();
        ctx.ui.notify("Codex usage cleared.", "info");
        return;
      }

      const cached = codexUsage.getReport();
      if (cached && codexUsage.isCacheFresh() && !options.value.refresh) {
        showCodexReport(ctx, cached, true);
        return;
      }

      try {
        const result = await queryUsage(ctx, options.value);
        if (!result.ok) {
          ctx.ui.notify(formatQueryErrors(result.errors), "error");
          return;
        }

        showCodexReport(ctx, result.report, false);

        if (options.value.statusline) {
          codexUsage.setReport(result.report, ctx);
        }
      } catch (error) {
        ctx.ui.notify(`Codex usage query failed: ${error instanceof Error ? error.message : String(error)}`, "error");
      }
    },
  });

  // ── Event Handlers ───────────────────────────────────────────────

  pi.on("session_start", (_event, ctx) => {
    runtime.thinkingLevel = pi.getThinkingLevel();
    installFooter(ctx);
    refreshCodexUsage(ctx);
  });

  pi.on("session_tree", (_event, ctx) => {
    installFooter(ctx);
    refresh();
    refreshCodexUsage(ctx);
  });

  pi.on("session_shutdown", (_event, ctx) => {
    if (ctx.mode === "tui") ctx.ui.setFooter(undefined);
    ctx.ui.setStatus(FOOTER_KEY, undefined);
    runtime.requestRender = undefined;
    codexUsage.clear();
    codexUsage.dispose();
  });

  pi.on("model_select", (event, ctx) => {
    refresh();
    refreshCodexUsage(ctx, false, event.model);
  });

  pi.on("agent_end", () => refresh());
  pi.on("turn_end", () => refresh());

  pi.on("thinking_level_select", (event) => {
    runtime.thinkingLevel = event.level;
    refresh();
  });
}

// ── Query Options ────────────────────────────────────────────────────

export interface CodexStatusOptions {
	clearStatusline: boolean;
	refresh: boolean;
	statusline: boolean;
	timeoutMs: number;
}

interface CodexRefreshOptions {
	showErrors?: boolean;
}

// ── Manager ──────────────────────────────────────────────────────────

export class CodexUsageManager {
	private cache: CachedReport | undefined;
	private refreshTimer: ReturnType<typeof setTimeout> | undefined;
	private requestId = 0;
	private _state: CodexUsageState = "idle";
	private onRender?: () => void;

	/** Current state: idle, loading, loaded, or error. */
	get state(): CodexUsageState {
		return this._state;
	}

	/** Latest cached report, or undefined if usage has not been fetched. */
	getReport(): CodexUsageReport | undefined {
		return this.cache?.report;
	}

	/** Whether the cache is still fresh. */
	isCacheFresh(): boolean {
		return this.cache !== undefined && Date.now() - this.cache.createdAt < CACHE_TTL_MS;
	}

	/** Bind the render callback. Called from the extension entry point. */
	setRenderCallback(onRender: (() => void) | undefined): void {
		this.onRender = onRender;
	}

	/** Cache a freshly queried report without issuing a second usage request. */
	setReport(report: CodexUsageReport, ctx?: ExtensionContext): void {
		this.requestId++;
		this.cache = { createdAt: Date.now(), report };
		this._state = "loaded";
		if (ctx) this.scheduleRefresh(ctx);
		else this.clearTimer();
		this.onRender?.();
	}

	/**
	 * Refresh Codex usage data when auth is available.
	 * - If cache is fresh and `force` is false, schedules next refresh only.
	 * - If no Codex auth is available and `showErrors` is false, returns to idle.
	 * - Otherwise fetches fresh data and caches it for any selected model.
	 */
	async refresh(
		ctx: ExtensionContext,
		force: boolean,
		model: CodexUsageModel | undefined = ctx.model,
		options: CodexRefreshOptions = {},
	): Promise<void> {
		const requestId = ++this.requestId;

		if (this.isCacheFresh() && !force) {
			this.scheduleRefresh(ctx);
			this._state = "loaded";
			this.onRender?.();
			return;
		}

		if (!this.cache) {
			this._state = "loading";
			this.onRender?.();
		}

		const result = await queryUsage(ctx, { timeoutMs: DEFAULT_TIMEOUT_MS });

		// Stale request guard
		if (requestId !== this.requestId) return;

		if (!result.ok) {
			const showErrors = options.showErrors ?? isOpenAICodexModel(model);
			this._state = showErrors ? "error" : this.cache ? "loaded" : "idle";
			if (showErrors || this.cache) this.scheduleRefresh(ctx);
			else this.clearTimer();
			this.onRender?.();
			return;
		}

		this.cache = { createdAt: Date.now(), report: result.report };
		this._state = "loaded";
		this.scheduleRefresh(ctx);
		this.onRender?.();
	}

	/** Clear all state (statusline disabled or session shutdown). */
	clear(): void {
		this.requestId++;
		this.clearTimer();
		this.cache = undefined;
		this._state = "idle";
		this.onRender?.();
	}

	/** Dispose all timers. */
	dispose(): void {
		this.clearTimer();
		this.onRender = undefined;
	}

	private scheduleRefresh(ctx: ExtensionContext): void {
		this.clearTimer();
		this.refreshTimer = setTimeout(() => {
			void this.refresh(ctx, true);
		}, CACHE_TTL_MS);
		this.refreshTimer.unref?.();
	}

	private clearTimer(): void {
		if (this.refreshTimer) clearTimeout(this.refreshTimer);
		this.refreshTimer = undefined;
	}
}

// ── Command Argument Parsing ─────────────────────────────────────────

export function parseCodexStatusArgs(
	args: string,
): { ok: true; value: CodexStatusOptions } | { ok: false; error: string } {
	const tokens = args.trim().split(/\s+/).filter(Boolean);
	let clearStatusline = false;
	let refresh = false;

